import{_ as r,C as e,o as s,c as l,ae as n,E as i}from"./chunks/framework.EHGTsUvI.js";const b=JSON.parse('{"title":"Características destacadas","description":"","frontmatter":{},"headers":[],"relativePath":"es/features.md","filePath":"es/features.md"}'),d={name:"es/features.md"};function c(u,a,m,p,h,_){const o=e("ApiMatrix"),t=e("PluginShowcase");return s(),l("div",null,[a[0]||(a[0]=n('<h1 id="caracteristicas-destacadas" tabindex="-1">Características destacadas <a class="header-anchor" href="#caracteristicas-destacadas" aria-label="Permalink to &quot;Características destacadas&quot;">​</a></h1><p>OTools integra herramientas, ecosistema de plugins y multitarea con Tabs en una plataforma de escritorio de alto rendimiento. Aquí tienes un resumen de las capacidades clave.</p><h2 id="_1-multitarea-con-tabs" tabindex="-1">1. Multitarea con Tabs <a class="header-anchor" href="#_1-multitarea-con-tabs" aria-label="Permalink to &quot;1. Multitarea con Tabs&quot;">​</a></h2><ul><li>Abre varias herramientas en paralelo y conserva el contexto.</li><li>Cambia rápido entre plugins sin recargar.</li><li>Ideal para flujos de productividad y menos cambios de ventana.</li></ul><h2 id="_2-ecosistema-de-plugins-oceano" tabindex="-1">2. Ecosistema de plugins “océano” <a class="header-anchor" href="#_2-ecosistema-de-plugins-oceano" aria-label="Permalink to &quot;2. Ecosistema de plugins “océano”&quot;">​</a></h2><ul><li>Herramientas integradas + plugins de la comunidad forman un ecosistema completo.</li><li>Actualizaciones en caliente, historial de versiones y distribución en marketplace.</li><li>Directorio unificado de plugins y acceso centralizado.</li></ul><h2 id="_3-runtime-de-escritorio-de-alto-rendimiento" tabindex="-1">3. Runtime de escritorio de alto rendimiento <a class="header-anchor" href="#_3-runtime-de-escritorio-de-alto-rendimiento" aria-label="Permalink to &quot;3. Runtime de escritorio de alto rendimiento&quot;">​</a></h2><ul><li>Llamadas locales rápidas y estables.</li><li>Bibliotecas dinámicas Native para ampliar el rendimiento.</li><li>Puente API unificado para llamadas consistentes.</li></ul><h2 id="_4-enfocado-en-desarrolladores" tabindex="-1">4. Enfocado en desarrolladores <a class="header-anchor" href="#_4-enfocado-en-desarrolladores" aria-label="Permalink to &quot;4. Enfocado en desarrolladores&quot;">​</a></h2><ul><li>Centro de desarrolladores integrado: crear, vincular y depurar.</li><li>Inicialización con un clic de proyectos Web/Vue y Rust nativo.</li><li>Flujo completo de empaquetado para distribución.</li></ul><h2 id="_5-modulos-integrados" tabindex="-1">5. Módulos integrados <a class="header-anchor" href="#_5-modulos-integrados" aria-label="Permalink to &quot;5. Módulos integrados&quot;">​</a></h2><ul><li>Gestión de proyectos Git y documentación asistida por IA</li><li>Herramientas de red HTTP / MQTT / FTP</li><li>Terminal Docker y SSH/SFTP</li><li>Gestión de bases de datos (DBM)</li><li>Captura y reproducción de paquetes (Pakcap)</li><li>Capturas, audio, disco y utilidades generales</li></ul>',12)),i(o),i(t)])}const g=r(d,[["render",c]]);export{b as __pageData,g as default};
